-- 179: ONE naming convention for product SKUs, owned by the database.
--
-- A SKU is PayCraft's catalogue id for a product: what `/config` lists, what an app asks to buy, what a
-- website puts in `/checkout/?plan=`. Until now anything matching the dashboard's loose
-- `[A-Za-z0-9._-]{1,128}` went in, so production holds three styles side by side — `pro-monthly`
-- (Reels Downloader, Hacker Keyboard), `cappy_plus_monthly`, and the store-id style
-- `com.mobilebytesensei.cappy.sub.week` that onboarding generated by reusing the Play/App Store product id
-- as the SKU. Every client and test then guesses which one a tenant uses.
--
-- THE convention (this file is its single source of truth; dashboard/lib/sku.ts mirrors the pattern and a
-- test pins the two together):
--
--     lowercase kebab-case — [a-z0-9]+ words joined by single hyphens, 2..64 chars
--     e.g. pro-monthly · pro-annual · plus-lifetime · coins-100
--
-- Store product ids are NOT SKUs: they keep their own columns (play_product_id, app_store_product_id) with
-- the stores' own rules (Play allows no hyphens; reverse-DNS is fine there).
--
-- Existing SKUs are grandfathered (decided 2026-11-10): renaming a live SKU breaks every shipped app build
-- that asks for it and every subscription row that names it. So the rule applies when a SKU is CREATED or
-- CHANGED — an upsert that re-writes an existing (tenant, sku) still passes, and editing any other column of
-- a grandfathered product is untouched.

CREATE OR REPLACE FUNCTION paycraft_sku_is_canonical(p_sku TEXT)
RETURNS BOOLEAN
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT p_sku IS NOT NULL
     AND length(p_sku) BETWEEN 2 AND 64
     AND p_sku ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
$$;

COMMENT ON FUNCTION paycraft_sku_is_canonical(TEXT) IS
  'THE SKU naming convention (migration 179): lowercase kebab-case, 2..64 chars, e.g. pro-monthly.';

CREATE OR REPLACE FUNCTION tenant_products_enforce_sku_convention()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF paycraft_sku_is_canonical(NEW.sku) THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.sku IS NOT DISTINCT FROM OLD.sku THEN
    RETURN NEW; -- a grandfathered product, edited without touching its SKU
  END IF;
  -- BEFORE INSERT also fires for `INSERT … ON CONFLICT (tenant_id, sku) DO UPDATE` (tenant_products_upsert):
  -- re-writing a product that already exists under this SKU is an edit, not a new SKU.
  IF TG_OP = 'INSERT' AND EXISTS (
    SELECT 1 FROM tenant_products WHERE tenant_id = NEW.tenant_id AND sku = NEW.sku
  ) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'sku_not_canonical: "%" — a SKU must be lowercase kebab-case, 2-64 characters (e.g. pro-monthly). Store product ids go in play_product_id / app_store_product_id.', NEW.sku
    USING ERRCODE = 'check_violation';
END;
$$;

DROP TRIGGER IF EXISTS tenant_products_sku_convention ON tenant_products;
CREATE TRIGGER tenant_products_sku_convention
  BEFORE INSERT OR UPDATE OF sku ON tenant_products
  FOR EACH ROW EXECUTE FUNCTION tenant_products_enforce_sku_convention();
